pub fn save_recording_chunk(session_id: String, chunk: Vec<u8>, chunk_index: u32) -> Result<String, String> {
    validate_session_id(&session_id)?;
    let dir = temp_recording_dir().join(&session_id);

// Calculate token expiry (Google tokens last 3600s, subtract 60s buffer)
let expires_in = token_data["expires_in"].as_u64().unwrap_or(3600);
let expires_at = std::time::SystemTime::now()
    .duration_since(std::time::UNIX_EPOCH)
    .unwrap_or_default()
    .as_secs()
    + expires_in
    - 60;

// Listen for widget events (stop / cancel)
const { listen } = await import('@tauri-apps/api/event');
listen('recording-stop', () => handleStop());
listen('recording-cancel', () => handleCancel());

// Proactively refresh if token is expired or expiring soon
const now = Math.floor(Date.now() / 1000);
if (appState.config.google_drive.expires_at > 0 && now >= appState.config.google_drive.expires_at) {
	logger.info('drive', 'Token expired, refreshing proactively...');
	token = await refreshDriveToken();
}
